params.command:
$ErrorActionPreference='Stop'
$dest = Join-Path $env:TEMP 'shipit-20260929-0915-agentcontrol-verify-2382b8e4'
if (Test-Path $dest) { Remove-Item -Recurse -Force $dest }
git clone --no-checkout https://github.com/fengie/mhw-mods.git $dest
git -C $dest fetch origin 2382b8e40b72326b199cd962a47acea87af99356
git -C $dest checkout --detach 2382b8e40b72326b199cd962a47acea87af99356
$actual = (git -C $dest rev-parse HEAD).Trim()
if ($actual -ne '2382b8e40b72326b199cd962a47acea87af99356') { throw "HEAD mismatch: $actual" }
Push-Location (Join-Path $dest 'tools\agent-control')
try {
  node --version
  npm run check
  npm test
} finally { Pop-Location }
Write-Output "VERIFIED_HEAD=$actual"
git -C $dest status --short
